import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class BFSResult {
        int[] dist;
        int[] parent;
        int far;

        BFSResult(int[] dist, int[] parent, int far) {
            this.dist = dist;
            this.parent = parent;
            this.far = far;
        }
    }

    @SuppressWarnings("unchecked")
    static List<Integer>[] createGraph(int n) {
        List<Integer>[] g = new List[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
        }
        return g;
    }

    static BFSResult bfs(List<Integer>[] g, int start) {
        int n = g.length;
        int[] dist = new int[n];
        int[] parent = new int[n];
        Arrays.fill(dist, -1);

        parent[start] = -1;
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[start] = 0;
        q.add(start);

        int far = start;

        while (!q.isEmpty()) {
            int u = q.removeFirst();

            if (dist[u] > dist[far]) {
                far = u;
            }

            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.addLast(v);
                }
            }
        }

        return new BFSResult(dist, parent, far);
    }

    static int findCenter(List<Integer>[] g) {
        int a = bfs(g, 0).far;
        BFSResult res = bfs(g, a);

        int b = res.far;
        int diameterEdges = res.dist[b];
        int v = b;
        int half = diameterEdges / 2;

        while (res.dist[v] > half) {
            v = res.parent[v];
        }

        return v + 1;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();

        List<Integer>[] circle = createGraph(N);
        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            circle[a].add(b);
            circle[b].add(a);
        }

        int centerCircle = findCenter(circle);

        List<Integer>[] square = createGraph(M);
        for (int i = 0; i < M - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            square[a].add(b);
            square[b].add(a);
        }

        int centerSquare = findCenter(square);

        System.out.println(centerCircle + " " + centerSquare);
    }
}
